INSERT INTO `tax_rules` VALUES ('TAX-001','{\"id\": \"TAX-001\", \"name\": \"Standard VAT (15%)\", \"rate\": 15, \"type\": \"VAT/GST\", \"appliesTo\": \"BOTH\", \"is_active\": true, \"created_at\": \"2026-08-12 22:32:45.335\", \"updated_at\": \"2026-08-29 22:07:48.466\", \"accountCode\": \"\", \"description\": \"Standard Ethiopian Value Added Tax rate of 15%\", \"isDeduction\": false, \"isInclusive\": false, \"ratePercent\": 15, \"is_inclusive\": false, \"gl_account_code\": \"2210\"}','2026-08-12 19:32:45.335','2026-09-29 07:52:50.911'),('TAX-002','{\"id\": \"TAX-002\", \"name\": \"Withholding Tax (TDS 2%)\", \"rate\": 2, \"type\": \"Withholding Tax (TDS)\", \"appliesTo\": \"BOTH\", \"is_active\": true, \"created_at\": \"2026-08-12 22:32:45.335\", \"updated_at\": \"2026-08-29 22:07:48.466\", \"accountCode\": \"2210\", \"description\": \"2% Tax Deducted at Source for commercial services\", \"isDeduction\": false, \"isInclusive\": false, \"ratePercent\": 2, \"is_inclusive\": false, \"gl_account_code\": \"2210\"}','2026-08-12 19:32:45.335','2026-09-29 07:52:50.907'),('TAX-003','{\"id\": \"TAX-003\", \"name\": \"Import Customs Duty (10%)\", \"rate\": 10, \"type\": \"Import Duty\", \"appliesTo\": \"BOTH\", \"is_active\": true, \"created_at\": \"2026-08-12 22:32:45.335\", \"updated_at\": \"2026-08-29 22:07:48.466\", \"accountCode\": \"2210\", \"description\": \"Customs duty rate on imported agricultural & tech goods\", \"isDeduction\": false, \"isInclusive\": false, \"ratePercent\": 10, \"is_inclusive\": false, \"gl_account_code\": \"2210\"}','2026-08-12 19:32:45.335','2026-09-29 07:52:50.903'),('TAX-TOT-2','{\"id\": \"TAX-TOT-2\", \"name\": \"Turnover Tax (2% TOT)\", \"type\": \"Turnover Tax (TOT)\", \"appliesTo\": \"SALES\", \"is_active\": true, \"created_at\": \"2026-08-29 11:49:31.181\", \"updated_at\": \"2026-09-28 13:20:57.811\", \"accountCode\": \"2000-05\", \"description\": \"2% Turnover Tax for non-VAT registered service transactions\", \"isDeduction\": false, \"isInclusive\": false, \"ratePercent\": 2}','2026-08-29 08:49:31.181','2026-09-29 07:52:50.900'),('TAX-VAT-15','{\"id\": \"TAX-VAT-15\", \"name\": \"Standard VAT (15%)\", \"type\": \"VAT/GST\", \"appliesTo\": \"BOTH\", \"is_active\": true, \"created_at\": \"2026-08-29 11:49:31.181\", \"updated_at\": \"2026-09-28 13:20:57.804\", \"accountCode\": \"2000-05\", \"description\": \"Standard 15% Ethiopian Value Added Tax (Output VAT / Input VAT)\", \"isDeduction\": false, \"isInclusive\": false, \"ratePercent\": 15}','2026-08-29 08:49:31.181','2026-09-29 07:52:50.896'),('TAX-WHT-2','{\"id\": \"TAX-WHT-2\", \"name\": \"Withholding Tax (2% Services)\", \"type\": \"Withholding Tax (TDS)\", \"appliesTo\": \"BOTH\", \"is_active\": true, \"created_at\": \"2026-08-29 11:49:31.181\", \"updated_at\": \"2026-09-28 13:20:57.808\", \"accountCode\": \"1320-06-01\", \"description\": \"2% Tax Deducted at Source for commercial service contracts\", \"isDeduction\": true, \"isInclusive\": false, \"ratePercent\": 2}','2026-08-29 08:49:31.181','2026-09-29 07:52:50.889'),('TAX-WHT-3','{\"id\": \"TAX-WHT-3\", \"name\": \"Withholding Tax (3% Goods/Rent)\", \"type\": \"Withholding Tax (TDS)\", \"appliesTo\": \"BOTH\", \"is_active\": true, \"created_at\": \"2026-08-29 11:49:31.181\", \"updated_at\": \"2026-09-28 13:20:57.810\", \"accountCode\": \"1320-06-01\", \"description\": \"3% Withholding Tax asset deducted on goods supplies and rental\", \"isDeduction\": true, \"isInclusive\": false, \"ratePercent\": 3}','2026-08-29 08:49:31.181','2026-09-29 07:52:50.885'),('TAX-ZERO','{\"id\": \"TAX-ZERO\", \"name\": \"Zero-Rated / Export Exempt (0%)\", \"type\": \"Exempt\", \"appliesTo\": \"BOTH\", \"is_active\": true, \"created_at\": \"2026-08-29 11:49:31.181\", \"updated_at\": \"2026-09-28 13:20:57.813\", \"accountCode\": \"2000-05\", \"description\": \"Zero-rated export commodities (Green Mung, Sesame) and exempt supplies\", \"isDeduction\": false, \"isInclusive\": false, \"ratePercent\": 0}','2026-08-29